-- Setup consent for "Set me up on Cloudflare". refresh_enc is the sealed
-- refresh token. The access token is not stored. Append-only: do not edit this file.
CREATE TABLE IF NOT EXISTS cloudflare_grant (
  "userId" TEXT NOT NULL PRIMARY KEY REFERENCES "user" ("id") ON DELETE CASCADE,
  "accountId" TEXT NOT NULL,
  choice TEXT NOT NULL,
  host TEXT NOT NULL,
  requested_scope TEXT NOT NULL,
  granted_scope TEXT,
  refresh_enc TEXT,
  access_expires_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
